        "text": "У воина доспех потерял 3 прочности. В городе ремонт у кузнеца обойдётся в 3 × 5 с = 15 с. Если у воина есть Кузнечное дело и ремонтный набор, он может сам отремонтировать за 3 часа и 3 единицы набора, потратив 0 монет. Это выгодно, но требует времени."
