        "text": "Кто платит: все, кто продаёт товары на рынках, ярмарках или перевозит их через границы княжества. Размер: 5–15% от стоимости товара (обычно 10%). Взимается при продаже или при въезде в город с товаром. Как платится: при регистрации товара на въезде или при заключении сделки на рынке. Купец должен предъявить товар и заплатить пошлину сборщику. Последствия неуплаты: конфискация товара и крупный штраф (вплоть до тройной стоимости товара)."
