        "kind": "paragraph",
        "text": "Эффект: при успешном сотворении и провале Избавления цель выполняет один конкретный приказ. В судебном эксперименте её понуждают повторить соответствующую магию, чтобы волхв сравнил след Живы с обнаруженным. Цель использует собственные навыки и Живу; неизвестных способностей заклинание ей не даёт. Эффект прекращается при потере концентрации, исполнении приказа или завершении срока."
