        "text": "Этот народ был рождён из искр молота Сварога, высеченных из самой сердцевины мира. Коренастые, плотные, невысокого роста (редко выше полутора метров), они кажутся вырубленными из гранита. Их густые волосы и бороды — мужские и женские — подобны руде: от пепельно-седых до смоляно-чёрных, а глаза часто повторяют этот цвет. Их лица крупны и суровы, как скалы, среди которых они обитают. Города Сварожичей — это не постройки на поверхности, а огромные чертоги, вырубленные в недрах гор, где кузнечный жар и стук молотов не стихают никогда. Секреты обработки металла, дарованные самим Сварогом, они впитывают с молоком матерей, а самый старый из их рода, чей возраст, засвидетельствованный в древних свитках, перешагнул шесть веков, помнит времена, когда люди ещё не населяли равнины. Они верны своему роду, который может насчитывать тысячи лет, и невероятно крепки телом. Каждый Сварожич — это кузнец и воин, чья сила и владение оружием столь же незыблемы, как горы, которые они называют домом."
