        "text": "Ремесленная Сноровка. Вы владеете одним набором редких инструментов (часовщика, механика, алхимика). Вы можете создавать простые хитроумные устройства (часы, ловушки), тратя время (1 час) и делая проверку Интеллекта + соответствующий навык."
