        "kind": "paragraph",
        "text": "Вы используете Искру вместо бодрости. Также при использовании заклинаний вы дополнительно тратите +1 Искру.\nБазовое значение = 15 + модификатор Ловкости.\nПри повышении уровня получаете 1к6 + мод. Ловкости Искра."
