        "kind": "paragraph",
        "text": "Активно (1/день): Вы можете потратить 5 благодать, чтобы на 1 минуту получить Слепое зрение (шестое чувство) в радиусе 10 саженей, ощущая присутствие всех живых и мёртвых существ."
