        "text": "Жертвы и Дар: Жертвы: Крепкий мёд, бычья кровь, закаленное оружие, доспехи побеждённого врага, клятвы верности. Дар: Перун дарует мужество, силу и ловкость воина, победу над врагом, защиту от тёмных сил, непоколебимость духа."
