        "kind": "paragraph",
        "text": "Активно (1/бой): Вы можете потратить 6 благодать, чтобы призвать Громовой удар. Враг в пределах даль должен пройти Избавление Силы, иначе получит состояние Ошеломление на 1 раунд."
