        "text": "Жертвы и Дар: Жертвы: Зерно, спелые плоды, хлеб, мёд, золото (символ солнца), благодарственные молитвы. Дар: Даждьбог дарует обильные урожаи, солнечное тепло, материальное благополучие честным трудом, удачу в делах."
