        "text": "Жертвы и Дар: Жертвы: Первая зелень, крашеные яйца, прыжки через костёр, хороводы, брачные обряды, щедрые возлияния. Дар: Ярило дарует неудержимую жизненную силу, страсть, радость жизни, плодовитость, энергию для новых начинаний."
