        "text": "Отвары преимущественно готовят из трав, без химического воздействия другими элементами. Зелья проходят более сложную обработку - от получения вытяжки до перегонки. Различие задаётся способом приготовления, а не только ценой или покупателем. Участие Живы в конкретных составах пока отдельно не определено; эффекты и ограничения сохраняются по правилам книги."
