        "text": "Дети играют в прятки, догонялки и простые игры с камешками, палочками и косточками. Взрослые собираются за беседой, песнями и рассказами; на праздниках устраивают пляски и состязания. В корчмах слушают гусляров и сказителей, на торгах смотрят представления скоморохов. Местные предпочтения не запрещают другие забавы и не меняют общий набор праздников."
