        "kind": "paragraph",
        "text": "Цены: дудка - 20 м, свирель работы мастера - 50 м, бубен - 1 с, простые гусли - 4 с, гудок со смычком - 5 с. Знакомая песня на заказ в корчме - 3 м, один музыкант на вечер - 1 с, три исполнителя - 3 с. Дорогу при найме в другое поселение оговаривают отдельно; уличному исполнителю дают добровольную плату."
