    "title": "14. Семья, род и наследство",
    "category": "Жизнь и обычаи Пармы",
    "blocks": [
      {
        "kind": "paragraph",
        "text": "Брак признают по согласию супругов после объявления перед родичами и свидетелями. Обряд проводит волхв, ведун или старший рода; к Ладе обращаются перед свадьбой. Семьи договариваются о месте жизни и хозяйстве, дарят молодым посильные припасы и вещи. Свадьбу сопровождают трапезой, песнями и состязаниями; общей обязательной цены свадьбы нет."
      },
      {
        "kind": "paragraph",
        "text": "Сироту принимают родичи или другая семья, при отсутствии близких помогает община. Взрослого могут принять в род решением родичей с общим объявлением. Побратимство означает взаимную помощь, но не автоматическое право на родовое имущество или власть."
      },
      {
        "kind": "paragraph",
        "text": "В наследовании сохраняют доли живых совладельцев. Личные вещи и долю умершего передают по объявленной воле или признанной грамоте; без распоряжения имущество остаётся ближайшей семье. Раздел решают родичи, спор - местный суд. Семейную реликвию доверяют подходящему хранителю. Наследование имущества не назначает князя, старосту или главу круга."
      },
      {
        "kind": "paragraph",
        "text": "Семья хранит рассказы, вещи и имена предков; состоятельные грамотные дома ведут записи. Обычные семейные события разыгрываются без обязательных бросков; важный конфликт решают по сюжету и существующим правилам. Для персонажа достаточно определить, кто ждёт его дома, кому он обязан и чью память хранит."
      }
    ],
    "source": "Единая книга 16"
