        "kind": "paragraph",
        "text": "Это сюжетные устройства. Здесь нет универсальной формулы их изготовления, готовых боевых характеристик или дополнительных способов получить Живу. Для конкретного приключения Сказитель задаёт действие устройства, признаки, условия остановки и цену последствий. Тлен и гнев богов применяются по книжным правилам; копирование текста не выдаёт их автоматически."
