        "text": "Найти причину повреждения моста между торговыми дорогами Гардарики и вечевых общин. Купец перегрузил настил, но обе стороны обвиняют соседей. Установление виновного сохранит совместный ремонт; сокрытие улик обернётся спором о пошлинах."
