        "text": "Проверить подлинность письма Асгарда, по которому староста собирает обязательную храмовую десятину. Письмо содержит только просьбу о пожертвовании. Раскрытие злоупотребления восстановит доверие к волхвам; сокрытие оставит их виновниками в глазах жителей."
