        "text": "Посредник предлагает выдать человека круга Теней Рода якобы для расчёта за пищу. Семья помощи не отрицает, но такого условия не принимала. Защита и поиск нового снабжения сорвут вербовку; выдача превратит поддержку в средство принуждения."
