        "text": "Культ просит изменить отметку пути, уверяя, что нужно скрыть стоянку от гарнизона. Новый маршрут ведёт обоз в опасный участок. Сообщение разведчикам позволит подготовить перехват; исполнение лишит крепость поставки и усилит давление на соседей."
