        "text": "Обычная беседа не требует дополнительного броска. Если персонаж применяет конкретное умение для торговли, сбора слухов или иного значимого действия, его книжные затраты, сроки, проверки и эффекты сохраняются. Это не вводит проверок бытового этикета и не отменяет изученные способности."
