        "text": "В Парме есть земледельцы, собиратели, травницы, бортники и лесорубы. Мельницы преимущественно водяные. Деревни делают запасы в общих амбарах, города - в городских хранилищах. Заготовки после урожая связаны с подготовкой дружин к дальним походам."
