        "kind": "paragraph",
        "text": "Расширенный лор описывает Верхнее как поселение земледельцев, выращивающих зерно, овощи и лён, а Травное - как поселение травников. В Харитонии уже предусмотрено земледелие на орошаемых землях. Эти сведения сохраняются; противоречащие новой карте старые привязки поселений не добавляются."
