        "text": "1. Хлебные культуры. Основу составляют рожь, ячмень, овёс, просо и пшеница. В прохладных лесных землях чаще сеют рожь, овёс и ячмень; на тёплых открытых землях больше возможностей для пшеницы и проса. Это предпочтения, а не запрет выращивать остальные культуры."
