        "text": "2. Огороды и сады. У домов выращивают репу, капусту, горох, лук и чеснок. Сады могут давать яблоки, груши, вишню и смородину там, где подходят условия и сорта. Огород кормит дом, крупные посевы обеспечивают запас и торговлю."
