        "text": "Сроки различаются между землями и культурами. Это хозяйственные этапы, а не четыре календарных сезона или единый день жатвы для всей карты. Книжный календарь сохраняет Оусень, Зиму и Весну и девять сороковников в Лѣте. Полугодие - половина Лѣта, а не шесть сороковников."
