        "kind": "paragraph",
        "text": "Лесные земли соединяют поля и огороды со сбором и бортничеством. Вечевые города получают часть зерна и сырья из округи и привозом. Вольница и Харитония дают значительную долю полевых продуктов по принятому торговому разделу; в Харитонии важны доступ к воде и орошение. В кочевых степях основой остаётся скотоводство, а зерно приобретают обменом или получают от оседлых соседей. Рубежи используют доступные безопасные поля и огороды, но гарнизоны также зависят от подвоза."
